// ── Helper: Get questions for a specific day (15-21) ─────────
// Maps day number to its question array
export function getDays15to21Questions(
  dayNumber: number,
  subtopicId?: string
): PracticeQ[] {
  let allQuestions: PracticeQ[] = [];

  // Select the correct day's question pool
  switch (dayNumber) {
    case 15: allQuestions = ALL_DAY_15_QUESTIONS; break;
    case 16: allQuestions = ALL_DAY_16_QUESTIONS; break;
    case 17: allQuestions = ALL_DAY_17_QUESTIONS; break;
    case 18: allQuestions = ALL_DAY_18_QUESTIONS; break;
    case 19: allQuestions = ALL_DAY_19_QUESTIONS; break;
    case 20: allQuestions = ALL_DAY_20_QUESTIONS; break;
    case 21: allQuestions = ALL_DAY_21_QUESTIONS; break;
    default: return [];
  }

  // If subtopicId provided, filter to that subtopic
  if (subtopicId) {
    const filtered = allQuestions.filter(q => q.subtopicId === subtopicId);
    // Return filtered if found, else return all day questions
    return filtered.length > 0 ? filtered : allQuestions;
  }

  return allQuestions;
}
